/// name ([hostedProviderKeyName], env/store) or the endpoint-scoped
/// `FA_KEY_<HOST>` entry (what the OAuth/SSO flows write). Keyless presets
/// (no key name) count as connected.
bool hostedProviderConnected(ProviderPreset preset) {
  final envName = hostedProviderKeyName(preset);
  if (envName == null) return true; // keyless
  final baseUrl = preset.baseUrl;
  if (baseUrl == null) return false;
  // The CLI/app shared chain (resolveEndpointKey): the app's host resolver
  // merges env/store per name, so envRead and storeRead are the same lookup.
  return harness.resolveEndpointKey(
        envNames: [envName],
        defaultBaseUrl: baseUrl,
        baseUrl: baseUrl,
        envRead: (name) {
          final value = FaUiHost.resolveKey(name, () => '');
          return value.isEmpty ? null : value;
        },
        storeRead: (name) {
          final value = FaUiHost.resolveKey(name, () => '');
          return value.isEmpty ? null : value;
        },
      ) !=
      null;
}

String? hostedProviderKeyName(ProviderPreset preset) => switch (preset) {
  ProviderPreset.aiin => 'AIIN_API_KEY',
  ProviderPreset.openrouter => 'OPENROUTER_API_KEY',
  ProviderPreset.ollamaCloud => 'OLLAMA_API_KEY',
  ProviderPreset.gemini => 'GEMINI_API_KEY',
  ProviderPreset.dial => 'DIAL_API_KEY',
  ProviderPreset.minimax => 'MINIMAX_API_KEY',
  _ => null,
};

/// Whether [baseUrl] addresses a DIAL Core endpoint (the chat path is
/// `/openai/deployments/...`, not `/chat/completions`).
bool _isDialBaseUrl(String url) => url.contains('ai-proxy.lab.epam.com');

/// DIAL deployments, the bundled ChatGPT Codex catalog, and Copilot (the
/// GitHub→Copilot token exchange) each have a dedicated wire dialect;
/// everything else probes the generic OpenAI `/models` (null hint). The
/// single mapping every model picker passes as the `provider:` argument —
/// identity-shaped hints beat URL-shape guessing, so a codex endpoint
/// stays on the codex wire even when its URL is edited.
String? modelsDispatchHintFor(String baseUrl) {
  if (_isDialBaseUrl(baseUrl)) return harness.dialDispatchHint;
  if (harness.isCopilotBaseUrl(baseUrl)) return harness.copilotDispatchHint;
  if (harness.isChatGptCodexEndpoint(baseUrl)) {
    return harness.chatgptCodexDispatchHint;
  }
  return null;
}

/// The dispatch hint for a picker selection backed by a registry entry: a
/// persisted identity ([CustomProvider.kind], saved by the connect flow)
/// wins over URL-shape matching. Null for free-typed endpoints — the URL
/// is the only signal there.
String? modelsDispatchHintForEntry(String? kind, String baseUrl) =>
    kind ?? modelsDispatchHintFor(baseUrl);

/// The chat provider kind for a registry-entry selection (issue #2156): a
/// persisted identity ([CustomProvider.kind]) wins, then the URL-shape
/// dialects ([modelsDispatchHintFor]), then Google's endpoint (the Gemini
/// adapter handles inlineData images); everything else speaks plain
/// openai-completions. The ONE mapping every picker and the agent-side
/// provider→live-model linkage apply, so a chat switched onto an entry
/// rides the same wire the model pickers dispatched it on.
String providerKindForEntry(String? kind, String baseUrl) {
  final hint = kind ?? modelsDispatchHintFor(baseUrl);
  if (hint != null) return hint;
  if (baseUrl.contains('generativelanguage.googleapis.com')) return 'google';
  return 'openai-completions';
}

